package com.aoo.bcg.common.id;
import java.time.Clock;import java.time.Instant;import java.util.Objects;import java.util.function.LongSupplier;
/** 63-bit Snowflake identity: UTC milliseconds, 10-bit node, 12-bit per-node sequence. */
public final class DistributedIdGenerator implements LongSupplier{private static final long EPOCH=Instant.parse("2025-01-01T00:00:00Z").toEpochMilli(),MAX_SEQUENCE=4095,MAX_CLOCK_WAIT_NANOS=10_000_000L;private final long nodeId;private final Clock clock;private long lastMillis=-1,sequence;public DistributedIdGenerator(long nodeId,Clock clock){if(nodeId<0||nodeId>1023)throw new IllegalArgumentException("nodeId must be 0..1023");this.nodeId=nodeId;this.clock=Objects.requireNonNull(clock);}@Override public synchronized long getAsLong(){long now=clock.millis();if(now<lastMillis)throw new IllegalStateException("clock moved backwards; ID generation stopped");if(now==lastMillis){sequence=(sequence+1)&MAX_SEQUENCE;if(sequence==0)now=awaitNext(lastMillis);}else sequence=0;lastMillis=now;long elapsed=now-EPOCH;if(elapsed<0||elapsed>((1L<<41)-1))throw new IllegalStateException("ID epoch exhausted");return(elapsed<<22)|(nodeId<<12)|sequence;}private long awaitNext(long previous){long deadline=System.nanoTime()+MAX_CLOCK_WAIT_NANOS;long now=clock.millis();while(now<=previous&&System.nanoTime()<deadline){java.util.concurrent.locks.LockSupport.parkNanos(100_000L);if(Thread.currentThread().isInterrupted())throw new IllegalStateException("ID clock wait interrupted");now=clock.millis();}if(now<=previous)throw new IllegalStateException("ID clock did not advance within CPU wait budget");return now;}}
